import {homography,project} from './vision.js?v=20261024-projects1';
export function stockCalibration(corners,width,height,imageWidth,imageHeight){if(![width,height].every(n=>Number.isFinite(n)&&n>=25&&n<=2500))throw Error('Enter measured foam width and length, 25–2500 mm.');if(!Array.isArray(corners)||corners.length!==4||corners.some(p=>!Array.isArray(p)||p.length!==2||p.some((n,i)=>!Number.isFinite(n)||n<0||n>[imageWidth,imageHeight][i])))throw Error('Select all four foam corners.');let area=0;for(let i=0;i<4;i++){const a=corners[i],b=corners[(i+1)%4],c=corners[(i+2)%4],cross=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);if(cross<=1)throw Error('Choose corners clockwise: top-left, top-right, bottom-right, bottom-left.');if(Math.hypot(b[0]-a[0],b[1]-a[1])<20)throw Error('Corners are too close together. Zoom in or retake closer.');area+=a[0]*b[1]-a[1]*b[0];}if(area/2<imageWidth*imageHeight*.03)throw Error('The foam is too small in this photo. Retake closer.');const target=[[0,0],[width,0],[width,height],[0,height]],H=homography(target,corners),inverse=homography(corners,target);return {H,inverse,width,height,corners:corners.map(p=>[...p])};}
export function rectifyStock(image,calibration,maxPixels=1600){const {width,height,H}=calibration,scale=Math.min(3,maxPixels/Math.max(width,height)),w=Math.max(1,Math.round(width*scale)),h=Math.max(1,Math.round(height*scale)),data=new Uint8ClampedArray(w*h*4),src=image.data;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const [u,v]=project(H,[(x+.5)/w*width,(y+.5)/h*height]),ix=Math.floor(u),iy=Math.floor(v),at=(y*w+x)*4;if(ix<0||iy<0||ix+1>=image.width||iy+1>=image.height){data[at]=data[at+1]=data[at+2]=255;data[at+3]=255;continue;}const dx=u-ix,dy=v-iy,k=(iy*image.width+ix)*4;for(let c=0;c<3;c++)data[at+c]=src[k+c]*(1-dx)*(1-dy)+src[k+4+c]*dx*(1-dy)+src[k+image.width*4+c]*(1-dx)*dy+src[k+image.width*4+4+c]*dx*dy;data[at+3]=255;}return {width:w,height:h,data};}
export function referenceCheck(points,expected){if(points.length!==2||!Number.isFinite(expected)||expected<=0||expected>3000)throw Error('Enter the measured reference length in millimetres.');const measured=Math.hypot(points[1][0]-points[0][0],points[1][1]-points[0][1]),error=Math.abs(measured-expected),tolerance=Math.max(.5,expected*.01);return {points:points.map(p=>[...p]),expected,measured,error,tolerance,passed:error<=tolerance};}
export function validPhoto(photo){if(photo===undefined||photo===null)return null;if(typeof photo!=='object'||typeof photo.id!=='string'||photo.id.length>100||!photo.id.length||photo.method!=='corners'||![photo.width,photo.height].every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=25&&n<=2500))throw Error('Invalid foam photo calibration');const p={id:photo.id,width:photo.width,height:photo.height,method:'corners'};if(photo.verification){const v=photo.verification;if(!Array.isArray(v.points)||v.points.length!==2||v.points.some(q=>!Array.isArray(q)||q.length!==2||q.some(n=>typeof n!=='number'||!Number.isFinite(n)||Math.abs(n)>5000)))throw Error('Invalid photo reference check');p.verification=referenceCheck(v.points,v.expected);}if(photo.image!==undefined){if(typeof photo.image!=='string'||photo.image.length>4000000||!/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/]+={0,2}$/.test(photo.image))throw Error('Invalid embedded foam photo');p.image=photo.image;}return p;}
